const PUZ_NEED = 6, PUZ_R = 62; // secondes à tenir sur la dalle, rayon de la dalle
const zarbiRange = p => ZARBI_L.slice(ZARBI_L.indexOf(p.from), ZARBI_L.indexOf(p.to) + 1);
