  if (z.done) { if ((z.t -= dt) <= 0) S.puz = null; return; }
  const on = S.players.some(p => !p.down && Math.hypot(p.x - z.x, p.y - z.y) < PUZ_R);
  z.prog = on ? z.prog + dt : Math.max(0, z.prog - dt * .5);
