  cx.fillStyle = "#6a6458"; cx.fillRect(x0 - 6, y0 - 6, S4 + 12, S4 + 12); cx.fillStyle = "#8c8574"; cx.fillRect(x0 - 3, y0 - 3, S4 + 6, S4 + 6);
